#!/usr/bin/env node
// Generates src/data/characterEntities.ts from the `character-entities` npm
// package (the ~2100 HTML5 named character references). Re-run this script
// and commit the regenerated file whenever the dependency is updated —
// do not hand-edit the generated file.
//
// Usage: node scripts/generate-character-entities.mjs

import { writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'
import { characterEntities } from 'character-entities'
import unicodeBlocks from 'unicode-blocks'

// Entities that must never be offered for insertion into a key label:
// - NewLine ('\n') would be misread as the KLE separator between the 12
//   label positions during @adamws/kle-serial JSON serialization, corrupting
//   the layout. See LABEL_ESCAPE_MAP guardrail in insert-character-into-label.ts.
// - Tab ('\t') is a non-printable control character with no visible glyph.
const EXCLUDED_NAMES = new Set(['NewLine', 'Tab'])

const outputPath = fileURLToPath(new URL('../src/data/characterEntities.ts', import.meta.url))

// Maps each raw Unicode block (from the `unicode-blocks` package, i.e. the
// official Unicode Blocks.txt) to one of a small set of user-facing tabs in
// the Character Picker. The `character-entities` dataset only ever touches
// ~30 distinct raw blocks (verified by running this script), so this table
// is exhaustive for the current dependency version — any block not listed
// here falls back to 'Symbols' (see BLOCK_TO_CATEGORY lookup below), which
// keeps a future `character-entities` update from silently dropping entries.
const BLOCK_TO_CATEGORY = {
  'Basic Latin': 'Latin',
  'Latin-1 Supplement': 'Latin',
  'Latin Extended-A': 'Latin',
  'Latin Extended-B': 'Latin',
  'Alphabetic Presentation Forms': 'Latin',
  'Greek and Coptic': 'Greek',
  Cyrillic: 'Cyrillic',
  'Mathematical Operators': 'Math',
  'Supplemental Mathematical Operators': 'Math',
  'Miscellaneous Mathematical Symbols-A': 'Math',
  'Miscellaneous Mathematical Symbols-B': 'Math',
  'Mathematical Alphanumeric Symbols': 'Math',
  Arrows: 'Arrows',
  'Supplemental Arrows-A': 'Arrows',
  'Supplemental Arrows-B': 'Arrows',
  'General Punctuation': 'Punctuation',
  'Miscellaneous Technical': 'Technical',
  'Control Pictures': 'Technical',
  'Geometric Shapes': 'Shapes',
  'Box Drawing': 'Shapes',
  'Block Elements': 'Shapes',
  'Letterlike Symbols': 'Symbols',
  'Miscellaneous Symbols': 'Symbols',
  Dingbats: 'Symbols',
  'Number Forms': 'Symbols',
  'Enclosed Alphanumerics': 'Symbols',
  'Currency Symbols': 'Symbols',
  'Spacing Modifier Letters': 'Diacritics',
  'Combining Diacritical Marks': 'Diacritics',
  'Combining Diacritical Marks for Symbols': 'Diacritics',
}
const FALLBACK_CATEGORY = 'Symbols'

function categoryForChar(char) {
  const block = unicodeBlocks.fromCodePoint(char.codePointAt(0))
  return (block && BLOCK_TO_CATEGORY[block.name]) || FALLBACK_CATEGORY
}

/** @type {Map<string, string[]>} char -> list of entity names that map to it */
const namesByChar = new Map()

for (const [name, char] of Object.entries(characterEntities)) {
  if (EXCLUDED_NAMES.has(name)) continue
  const existing = namesByChar.get(char)
  if (existing) {
    existing.push(name)
  } else {
    namesByChar.set(char, [name])
  }
}

function pickCanonicalName(names) {
  const lowerCaseNames = names.filter((name) => name === name.toLowerCase())
  const pool = lowerCaseNames.length > 0 ? lowerCaseNames : names
  return pool.slice().sort((a, b) => a.length - b.length || a.localeCompare(b))[0]
}

const entities = Array.from(namesByChar.entries()).map(([char, names]) => ({
  name: pickCanonicalName(names),
  char,
  codepoint: char.codePointAt(0),
  category: categoryForChar(char),
}))

entities.sort((a, b) => a.name.localeCompare(b.name))

const header = `// Generated by scripts/generate-character-entities.mjs from the
// \`character-entities\` npm package. Do not hand-edit — re-run the script
// and commit the regenerated file instead.

export type CharacterCategory =
  | 'Latin'
  | 'Greek'
  | 'Cyrillic'
  | 'Math'
  | 'Arrows'
  | 'Punctuation'
  | 'Technical'
  | 'Shapes'
  | 'Symbols'
  | 'Diacritics'

export interface CharacterEntity {
  name: string
  char: string
  codepoint: number
  category: CharacterCategory
}

export const CHARACTER_ENTITIES: CharacterEntity[] = [
`

const body = entities
  .map(
    (entity) =>
      `  { name: ${JSON.stringify(entity.name)}, char: ${JSON.stringify(entity.char)}, codepoint: 0x${entity.codepoint.toString(16)}, category: ${JSON.stringify(entity.category)} },`,
  )
  .join('\n')

const footer = `\n]\n`

writeFileSync(outputPath, header + body + footer, 'utf-8')

console.log(`Wrote ${entities.length} character entities to ${outputPath}`)
